WITH dates AS (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate>DATE_ADD(DATE_ADD(DATE_TRUNC('2026-04-14', 'YEAR'), INTERVAL '2' MONTH), INTERVAL '8' DAY) GROUP BY bizdate ORDER BY bizdate ASC LIMIT 3), qualified AS (SELECT b.mktcode,b.tgtcode FROM `newzl`.`hsj_stock_hq_basic` b JOIN dates d ON d.bizdate=b.bizdate GROUP BY b.mktcode,b.tgtcode HAVING COUNT(*)>0 AND SUM(CASE WHEN b.volume>0 THEN 1 ELSE 0 END)=COUNT(*)) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
